import "server-only";
import "./trust-system-ca";
import { createStatamicClient } from "@headquery/statamic";
// Registers the generated schema (module augmentation). Regenerated by `pnpm types` / `pnpm dev`.
import type {} from "./cms";

const baseUrl = process.env.HEADQUERY_BASE_URL;

if (!baseUrl) {
  throw new Error(
    "Set HEADQUERY_BASE_URL in playgrounds/statamic-next/.env.local",
  );
}

export const cms = createStatamicClient({
  baseUrl,
  // Next's data cache: every GET URL is deterministic, so it doubles as the cache key.
  fetchOptions: { next: { revalidate: 60 } },
});

/** Turns Statamic's relative asset URLs (`/assets/x.svg`) into absolute ones. */
export function absolute(url: string): string {
  return new URL(url, baseUrl).toString();
}
